function maxSum(nums) {
  const seen = new Set();
  let total = 0;
  let largest = nums[0];
  for (const value of nums) {
    largest = Math.max(largest, value);
    if (value > 0 && !seen.has(value)) {
      seen.add(value);
      total += value;
    }
  }
  if (largest <= 0) {
    return largest;
  }
  return total;
}

