function maxSum(nums) {
  // Deleting everything else turns any non-empty subsequence into the whole array, so try every one
  // whose values are all different.
  const n = nums.length;
  let best = -Infinity;
  for (let mask = 1; mask < (1 << n); mask++) {
    const kept = [];
    for (let i = 0; i < n; i++) if ((mask >> i) & 1) kept.push(nums[i]);
    let distinct = true;
    for (let a = 0; a < kept.length; a++)
      for (let b = a + 1; b < kept.length; b++)
        if (kept[a] === kept[b]) distinct = false;
    if (distinct) best = Math.max(best, kept.reduce((sum, v) => sum + v, 0));
  }
  return best;
}

