function generate(rand, size) {
  const pick = count => Math.floor(rand() * count);
  const n = size === 'large' ? 90 + pick(11) : 1 + pick(10);
  // Narrow ranges repeat values often; ranges without positive values exercise the single-value answer.
  const [low, high] = [[-100, 100], [-100, 100], [-5, 5], [-100, -1], [-3, 0], [0, 2]][pick(6)];
  return [Array.from({ length: n }, () => low + pick(high - low + 1))];
}
